# Correct the background detection - it should be GLOBAL, not per-row!
# Background = min value across ALL cells in the grid

def transform_rule_correct_global_bg(grid):
    """Transform using GLOBAL background value (min across entire grid)."""
    # Get global background
    all_values = set()
    for row in grid:
        all_values.update(row)
    bg = min(all_values)

    result = []
    for row in grid:
        if len(set(row)) == 1:
            result.append(list(row))
            continue

        # Check if row starts with >=3 consecutive non-bg identical values
        if row[0] != bg:
            run_len = 1
            for v in row[1:]:
                if v == row[0]:
                    run_len += 1
                else:
                    break

            if run_len >= 3:
                # Fill entire row with 2 * trigger value
                new_row = [2 * row[0]] * len(row)
                result.append(new_row)
            else:
                result.append(list(row))
        else:
            result.append(list(row))

    return result

