# Try using MODE (most frequent) as background instead of MIN
from collections import Counter

def get_mode(values):
    counter = Counter(values)
    return counter.most_common(1)[0][0]

def transform_rule_mode_bg(grid):
    """Transform using MODE as background."""
    result = []
    for row in grid:
        vals_in_row = set(row)

        # Check if uniform
        if len(vals_in_row) == 1:
            result.append(list(row))
            continue

        # Get background as most common value
        bg = get_mode(row)

        # Check if row starts with >=3 consecutive non-bg identical values
        if row[0] != bg:
            run_len = 1
            for v in row[1:]:
                if v == row[0]:
                    run_len += 1
                else:
                    break

            if run_len >= 3:
                new_row = [2 * row[0]] * len(row)
                result.append(new_row)
            else:
                result.append(list(row))
        else:
            result.append(list(row))

    return result

